/**
 * Test supplementing a doc field with arbitrary content from POJO
 *
 * @throws Exception
 */
@Test
public void testSupplementExistingField() throws Exception {
    conf = NutchConfiguration.create();
    conf.set("index.arbitrary.function.count", "2");
    conf.set("index.arbitrary.fieldName.0", "foo");
    conf.set("index.arbitrary.className.0", "org.apache.nutch.indexer.arbitrary.Echo");
    conf.set("index.arbitrary.constructorArgs.0", "Arbitrary text to add - bar");
    conf.set("index.arbitrary.methodName.0", "getText");
    conf.set("index.arbitrary.fieldName.1", "description");
    conf.set("index.arbitrary.className.1", "org.apache.nutch.indexer.arbitrary.Multiplier");
    conf.set("index.arbitrary.constructorArgs.1", "");
    conf.set("index.arbitrary.methodName.1", "getProduct");
    conf.set("index.arbitrary.methodArgs.1", "-1,3.14");
    filter = new ArbitraryIndexingFilter();
    Assert.assertNotNull("No filter exists for testSupplementExistingField", filter);
    filter.setConf(conf);
    doc = new NutchDocument();
    Assert.assertNotNull("doc doesn't exist", doc);
    doc.add("description", "irrational");
    Assert.assertFalse("doc is empty", doc.getFieldNames().isEmpty());
    Assert.assertEquals("field description does not have exactly one value", 1, doc.getField("description").getValues().size());
    Assert.assertTrue("field description does not have initial value 'irrational'", doc.getField("description").getValues().contains("irrational"));
    try {
        filter.filter(doc, parse, url, crawlDatum, inlinks);
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail(e.getMessage());
    }
    Assert.assertTrue("doc doesn't have new field with arbitrary value", doc.getField("foo").getValues().contains("Arbitrary text to add - bar"));
    Assert.assertEquals("field description does not have 2 values", 2, doc.getField("description").getValues().size());
    Assert.assertTrue("field description original value gone", doc.getField("description").getValues().contains("irrational"));
    Assert.assertTrue("field description missing new value", doc.getField("description").getValues().contains("-3.14"));
}

/**
 * Test overwriting a doc field with arbitrary content from POJO
 *
 * @throws Exception
 */
@Test
public void testOverwritingExistingField() throws Exception {
    conf = NutchConfiguration.create();
    conf.set("index.arbitrary.function.count", "3");
    conf.set("index.arbitrary.fieldName.0", "foo");
    conf.set("index.arbitrary.className.0", "org.apache.nutch.indexer.arbitrary.Echo");
    conf.set("index.arbitrary.constructorArgs.0", "Arbitrary text to add - bar");
    conf.set("index.arbitrary.methodName.0", "getText");
    conf.set("index.arbitrary.fieldName.1", "description");
    conf.set("index.arbitrary.className.1", "org.apache.nutch.indexer.arbitrary.Multiplier");
    conf.set("index.arbitrary.methodArgs.1", "-1,3.14159265");
    conf.set("index.arbitrary.methodName.1", "getProduct");
    conf.set("index.arbitrary.fieldName.2", "philosopher");
    conf.set("index.arbitrary.className.2", "org.apache.nutch.indexer.arbitrary.Echo");
    conf.set("index.arbitrary.constructorArgs.2", "Popeye");
    conf.set("index.arbitrary.methodName.2", "getText");
    conf.set("index.arbitrary.overwrite.2", "true");
    filter = new ArbitraryIndexingFilter();
    Assert.assertNotNull("No filter exists for testOverwritingExistingField", filter);
    filter.setConf(conf);
    Assert.assertNotNull("conf does not exist", conf);
    doc = new NutchDocument();
    Assert.assertNotNull("doc does not exist", doc);
    doc.add("description", "irrational");
    doc.add("philosopher", "Socrates");
    Assert.assertEquals("field description does not have exactly one value", 1, doc.getField("description").getValues().size());
    Assert.assertEquals("field philosopher does not have exactly one value", 1, doc.getField("philosopher").getValues().size());
    Assert.assertTrue("field description does not have initial value 'irrational'", doc.getField("description").getValues().contains("irrational"));
    Assert.assertTrue("field philosopher does not have initial value 'Socrates'", doc.getField("philosopher").getValues().contains("Socrates"));
    try {
        filter.filter(doc, parse, url, crawlDatum, inlinks);
    } catch (Exception e) {
        e.printStackTrace(System.out);
        Assert.fail(e.getMessage());
    }
    Assert.assertNotNull(doc);
    Assert.assertEquals("field philosopher no longer has only one value", 1, doc.getField("philosopher").getValues().size());
    Assert.assertFalse("field philosopher's original value 'Socrates' NOT overwritten", doc.getField("philosopher").getValues().contains("Socrates"));
    Assert.assertTrue("field philosopher does not have new value 'Popeye'", doc.getField("philosopher").getValues().contains("Popeye"));
}

@Test
public void testBasicIndexingFilter() throws Exception {
    Configuration conf = NutchConfiguration.create();
    conf.setInt("indexer.max.title.length", 10);
    conf.setBoolean("indexer.add.domain", true);
    conf.setInt("indexer.max.content.length", 20);
    BasicIndexingFilter filter = new BasicIndexingFilter();
    filter.setConf(conf);
    Assert.assertNotNull(filter);
    NutchDocument doc = new NutchDocument();
    String title = "The Foo Page";
    Outlink[] outlinks = new Outlink[] { new Outlink("http://foo.com/", "Foo") };
    Metadata metaData = new Metadata();
    metaData.add("Language", "en/us");
    ParseData parseData = new ParseData(ParseStatus.STATUS_SUCCESS, title, outlinks, metaData);
    ParseImpl parse = new ParseImpl("this is a sample foo bar page. hope you enjoy it.", parseData);
    CrawlDatum crawlDatum = new CrawlDatum();
    crawlDatum.setFetchTime(100L);
    Inlinks inlinks = new Inlinks();
    try {
        filter.filter(doc, parse, new Text("http://nutch.apache.org/index.html"), crawlDatum, inlinks);
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail(e.getMessage());
    }
    Assert.assertNotNull(doc);
    Assert.assertEquals("test title, expect \"The Foo Pa\"", "The Foo Pa", doc.getField("title").getValues().get(0));
    Assert.assertEquals("test domain, expect \"apache.org\"", "apache.org", doc.getField("domain").getValues().get(0));
    Assert.assertEquals("test host, expect \"nutch.apache.org\"", "nutch.apache.org", doc.getField("host").getValues().get(0));
    Assert.assertEquals("test url, expect \"http://nutch.apache.org/index.html\"", "http://nutch.apache.org/index.html", doc.getField("url").getValues().get(0));
    Assert.assertEquals("test content", "this is a sample foo", doc.getField("content").getValues().get(0));
    Assert.assertEquals("test fetch time", new Date(100L), (Date) doc.getField("tstamp").getValues().get(0));
}

