/**
 * NUTCH-2729 Check for http.content.limit defined in nutch-site-test.xml:
 * whether content is truncated to the configured 64 kB and whether it is
 * properly marked as truncated.
 */
@Test
public void testTruncationMarking() throws Exception {
    int[] kBs = { 63, 64, 65 };
    for (int kB : kBs) {
        StringBuilder response = new StringBuilder();
        response.append(responseHeader);
        response.append("Content-Type: text/plain\r\nContent-Length: " + (kB * 1024) + "\r\n\r\n");
        for (int i = 0; i < kB; i++) {
            for (int j = 0; j < 16; j++) {
                // 16 chunks a 64 bytes = 1 kB
                response.append("abcdefghijklmnopqurstuvxyz0123456789-ABCDEFGHIJKLMNOPQURSTUVXYZ\n");
            }
        }
        launchServer(response.toString());
        ProtocolOutput fetched = fetchPage("/", 200);
        assertEquals("Content not truncated according to http.content.limit", Math.min(kB * 1024, 65536), fetched.getContent().getContent().length);
        if (kB * 1024 > 65536) {
            assertNotNull("Content truncation not marked", fetched.getContent().getMetadata().get(Response.TRUNCATED_CONTENT));
            assertEquals("Content truncation not marked", Response.TruncatedContentReason.LENGTH.toString().toLowerCase(), fetched.getContent().getMetadata().get(Response.TRUNCATED_CONTENT_REASON));
        }
        // need to close server before next loop iteration
        server.close();
    }
}

/**
 * NUTCH-2729 Check for http.content.limit defined in nutch-site-test.xml:
 * whether content is truncated to the configured 64 kB and whether it is
 * properly marked as truncated.
 */
@Test
public void testTruncationMarkingGzip() throws Exception {
    int[] kBs = { 63, 64, 65 };
    for (int kB : kBs) {
        StringBuilder payload = new StringBuilder();
        for (int i = 0; i < kB; i++) {
            for (int j = 0; j < 16; j++) {
                // 16 chunks a 64 bytes = 1 kB
                payload.append("abcdefghijklmnopqurstuvxyz0123456789-ABCDEFGHIJKLMNOPQURSTUVXYZ\n");
            }
        }
        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
        GZIPOutputStream gzip = new GZIPOutputStream(bytes);
        gzip.write(payload.toString().getBytes(StandardCharsets.UTF_8));
        gzip.close();
        StringBuilder responseHead = new StringBuilder();
        responseHead.append(responseHeader);
        responseHead.append("Content-Type: text/plain\r\nContent-Length: " + bytes.size() + "\r\nContent-Encoding: gzip\r\n\r\n");
        ByteArrayOutputStream response = new ByteArrayOutputStream();
        response.write(responseHead.toString().getBytes(StandardCharsets.UTF_8));
        response.write(bytes.toByteArray());
        launchServer("/", response.toByteArray());
        ProtocolOutput fetched = fetchPage("/", 200);
        assertEquals("Content not truncated according to http.content.limit", Math.min(kB * 1024, 65536), fetched.getContent().getContent().length);
        if (kB * 1024 > 65536) {
            assertNotNull("Content truncation not marked", fetched.getContent().getMetadata().get(Response.TRUNCATED_CONTENT));
            assertEquals("Content truncation not marked", Response.TruncatedContentReason.LENGTH.toString().toLowerCase(), fetched.getContent().getMetadata().get(Response.TRUNCATED_CONTENT_REASON));
        }
